  \node at (1.5,0.45) {$K_2$};
  \node at (2.5,0.45) {$K_3$};
  \node at (3.5,0.45) {$K_N$};
  \draw[->,blue,thick] (0.55,-0.5) -- (1.45,-0.5) node[midway,below] {$G_{3/2}$};
  \draw[->,blue,thick] (1.55,-0.5) -- (2.45,-0.5) node[midway,below] {$G_{5/2}$};
